{"CommandLine":"~/.ansible/kssh -u superuser 172.30.198.33 '
cat << '\''EOF'\'' | sudo tee /etc/nginx/sites-available/02-extranetclient.outremer-telecom.fr.conf > /dev/null
server {
    listen              172.30.198.33:443 ssl http2 reuseport;
    server_name         extranetclient.outremer-telecom.fr;

    # SSL
    ssl_certificate     /etc/letsencrypt/live/extranetclient.outremer-telecom.fr/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/extranetclient.outremer-telecom.fr/privkey.pem;

    # security
    include             nginxconfig.io/security.conf;

    # logging
    access_log          /var/log/nginx/extranetclient.outremer-telecom.fr-access.log;
    error_log           /var/log/nginx/extranetclient.outremer-telecom.fr-error.log warn;

    # Redirection explicite racine → /centreon/
    location = / {
        return 301 /centreon/;
    }

    # Location block to forward LoRaWAN traffic to backend server on port 8443
    location /lorawan/data {
        proxy_pass http://172.30.198.49:8443/lorawan/data;
        include nginxconfig.io/proxy.conf;

        # Standard proxy headers
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Ssl on;

        # Ensure Nginx passes all custom and standard client request headers
        proxy_pass_request_headers on;

        # Allow extra large or custom header buffers if needed
        proxy_headers_hash_max_size 1024;
        proxy_headers_hash_bucket_size 128;
    }    

    # reverse proxy vers Centreon Web backend
    location / {
        proxy_pass http://172.30.198.49;
        include    nginxconfig.io/proxy.conf;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Ssl   on;
        proxy_redirect http:// https://;
        proxy_headers_hash_max_size 1024;
        proxy_headers_hash_bucket_size 128;
    }

    # additional config
    include nginxconfig.io/general.conf;
}

# HTTP redirect
server {
    listen      172.30.198.33:80 reuseport;
    server_name extranetclient.outremer-telecom.fr;
    return      301 https://$host$request_uri;
}

# HTTPS redirect MAP
server {
    listen              9443 ssl http2 reuseport;
    server_name         map.extranetclient.outremer-telecom.fr extranetclient.outremer-telecom.fr 109.62.64.18;

    # SSL (même certificat Let'\''s Encrypt que :443)
    ssl_certificate     /etc/letsencrypt/live/extranetclient.outremer-telecom.fr/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/extranetclient.outremer-telecom.fr/privkey.pem;

    # security
    include             nginxconfig.io/security.conf;

    # logging (nouveaux fichiers dédiés — pour ne pas polluer les logs du :443)
    access_log          /var/log/nginx/extranetclient.outremer-telecom.fr-9443-access.log;
    error_log           /var/log/nginx/extranetclient.outremer-telecom.fr-9443-error.log warn;

    # Redirection explicite racine → /centreon-map/
    location = / {
        return 301 /centreon-map/;
    }

    # reverse proxy vers Map (Tomcat HTTPS sur port 9443)
    location / {
        proxy_pass                 https://172.30.198.50:9443;
        proxy_ssl_verify           off;

        include                    nginxconfig.io/proxy.conf;
        proxy_set_header Host      $http_host;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Ssl   on;
        proxy_set_header X-Forwarded-Port  9443;

        proxy_redirect             http:// https://;
        proxy_headers_hash_max_size   1024;
        proxy_headers_hash_bucket_size 128;
    }

    # additional config
    include nginxconfig.io/general.conf;
}
EOF

# Test syntax and reload
sudo nginx -t && sudo systemctl reload nginx
'","Cwd":"/home/koby","WaitMsBeforeAsync":5000,"toolAction":"Running command","toolSummary":"Deploy perfected vhost on reverse proxy"}
